from lib import *
L = lambda *a, **k: lesson(19, "A0", *a, **k)
V = "verb"
L(1, "Я прокидаюся о сьомій", "Розповісти, що ви робите вранці, і о котрій.",
 "Про звичні дії кажуть просто: I + дієслово. I get up at seven. Час ставлять у кінці з at. Wake up — прокинутися, get up — встати з ліжка: це дві різні дії.",
 [W("wake up", "/ˌweɪk ˈʌp/", V, "прокидатися", "I wake up at six.", "Я прокидаюся о шостій."),
  W("get up", "/ˌɡet ˈʌp/", V, "вставати", "I get up at seven.", "Я встаю о сьомій."),
  W("have a shower", "/ˌhæv ə ˈʃaʊə/", V, "приймати душ", "I have a shower.", "Я приймаю душ."),
  W("brush my teeth", "/ˌbrʌʃ maɪ ˈtiːθ/", V, "чистити зуби", "I brush my teeth.", "Я чищу зуби."),
  W("get dressed", "/ˌɡet ˈdrest/", V, "одягатися", "I get dressed.", "Я одягаюся."),
  W("have breakfast", "/ˌhæv ˈbrekfəst/", V, "снідати", "I have breakfast at eight.", "Я снідаю о восьмій.")],
 [li("Can I sit here?", "Повторимо. Ви дозволяєте. Що відповісти?", ["Yes, of course.", "I'm afraid, of course.", "Yes, you can't."], "Yes, of course."),
  mt([("wake up", "прокидатися"), ("get up", "вставати"), ("get dressed", "одягатися"), ("have breakfast", "снідати")], "Чотири ранкові дії."),
  mt([("have a shower", "приймати душ"), ("brush my teeth", "чистити зуби"), ("have lunch", "обідати"), ("have dinner", "вечеряти")], "З їжею й душем англійською кажуть have."),
  liu("I get up at half past six.", "Прослухайте. О котрій людина встає?", ["О 6:30", "О 7:30", "О 6:15"], "Half past six — 6:30."),
  mcu("Що буває першим?", ["wake up", "get up", "get dressed"], "Спочатку прокидаються — wake up, потім встають — get up."),
  fb("I ___ a shower in the morning.", ["have", "do", "am"], "Have a shower."),
  fb("I brush my ___.", ["teeth", "shower", "breakfast"], "Brush my teeth — чистити зуби."),
  fb("I get up ___ seven o'clock.", ["at", "on", "in"], "Перед годиною — at."),
  liu("I wake up at six, but I get up at seven.", "Прослухайте. О котрій людина встає з ліжка?", ["О сьомій", "О шостій", "О восьмій"], "Get up at seven."),
  bs("Я снідаю о восьмій.", ["I", "have", "breakfast", "at", "eight"], ["am", "on"], "I have breakfast at eight."),
  tr("Я встаю о сьомій.", ["I get up at seven", "I get up at seven o'clock"], "I get up at seven."),
  li("What time do you get up?", "Ви встаєте о шостій. Що відповісти?", ["I get up at six.", "I'm get up six.", "I get up on six."], "I get up at six.")])
L(2, "Дорога на роботу", "Розповісти, коли ви виходите з дому і як дістаєтеся на роботу.",
 "Транспорт називають через by: by bus, by car, by train. Пішки — on foot або просто I walk. Leave home — виходити з дому. Start work — починати роботу. Перед work і home у цих виразах немає артикля.",
 [W("leave", "/liːv/", V, "виходити, залишати", "I leave home at eight.", "Я виходжу з дому о восьмій."),
  W("walk", "/wɔːk/", V, "іти пішки", "I walk to work.", "Я ходжу на роботу пішки."),
  W("take", "/teɪk/", V, "їхати (транспортом); брати", "I take the bus.", "Я їду автобусом."),
  W("by car", "/baɪ ˈkɑː/", "phrase", "машиною", "I go to work by car.", "Я їжджу на роботу машиною."),
  W("on foot", "/ɒn ˈfʊt/", "phrase", "пішки", "I go on foot.", "Я ходжу пішки."),
  W("start", "/stɑːt/", V, "починати", "I start work at nine.", "Я починаю роботу о дев'ятій.")],
 [fb("I ___ breakfast at half past seven.", ["have", "get", "do"], "Have breakfast.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("leave", "виходити"), ("walk", "іти пішки"), ("take", "їхати транспортом"), ("start", "починати")], "У walk літера l не вимовляється."),
  mt([("by car", "машиною"), ("by bus", "автобусом"), ("by train", "поїздом"), ("on foot", "пішки")], "Транспорт — by, пішки — on foot."),
  liu("I leave home at quarter to eight.", "Прослухайте. О котрій людина виходить?", ["О 7:45", "О 8:15", "О 8:45"], "Quarter to eight — 7:45."),
  fb("I go to work ___ bus.", ["by", "on", "with"], "By bus."),
  fb("I ___ the train to work.", ["take", "walk", "go"], "Take the train — їхати поїздом."),
  mc("Як правильно?", ["I start work at nine.", "I start the work at nine.", "I start to the work at nine."], "Start work — без артикля."),
  mc("Як сказати «Я ходжу на роботу пішки»?", ["I walk to work.", "I walk by foot.", "I go on the foot work."], "I walk to work або I go to work on foot."),
  liu("I take the bus at eight and I start work at nine.", "Прослухайте. Коли людина починає роботу?", ["О дев'ятій", "О восьмій", "О десятій"], "Start work at nine."),
  bs("Я виходжу з дому о восьмій.", ["I", "leave", "home", "at", "eight"], ["the", "by"], "I leave home at eight."),
  tr("Я їжджу на роботу машиною.", ["I go to work by car", "I drive to work"], "I go to work by car."),
  li("How do you go to work?", "Ви їздите автобусом. Що відповісти?", ["By bus.", "On bus.", "With a bus."], "By bus.")])
L(3, "Завжди, часто, ніколи", "Сказати, як часто ви щось робите.",
 "Слова частоти: always (100 %) — usually — often — sometimes — never (0 %). Вони стоять перед дієсловом: I always have breakfast. Але після am / is / are: I'm never late. З never слово not уже не потрібне.",
 [W("always", "/ˈɔːlweɪz/", "adverb", "завжди", "I always have breakfast.", "Я завжди снідаю."),
  W("often", "/ˈɒfn/", "adverb", "часто", "I often walk to work.", "Я часто ходжу на роботу пішки."),
  W("sometimes", "/ˈsʌmtaɪmz/", "adverb", "іноді", "I sometimes take the bus.", "Іноді я їжджу автобусом."),
  W("never", "/ˈnevə/", "adverb", "ніколи", "I never drink coffee.", "Я ніколи не п'ю кави.")],
 [fb("I go to work ___ car.", ["by", "on", "in"], "By car.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("always", "завжди"), ("often", "часто"), ("sometimes", "іноді"), ("never", "ніколи"), ("usually", "зазвичай")], "Від 100 % до нуля: always, usually, often, sometimes, never."),
  mcu("Яке слово означає найбільшу частоту?", ["always", "often", "sometimes"], "Always — завжди."),
  mc("Як правильно?", ["I always get up at six.", "I get always up at six.", "Always I get up at six."], "Слово частоти — перед дієсловом."),
  mc("Як правильно?", ["I'm never late.", "I never am late.", "I'm late never."], "Після am / is / are слово частоти стоїть за дієсловом."),
  mc("Як сказати «Я ніколи не п'ю кави»?", ["I never drink coffee.", "I don't never drink coffee.", "I never don't drink coffee."], "З never слово not не потрібне."),
  liu("I sometimes walk to work.", "Прослухайте. Як часто людина ходить пішки?", ["Іноді", "Завжди", "Ніколи"], "Sometimes — іноді."),
  liu("She's often late.", "Прослухайте. Що ви дізналися?", ["Вона часто запізнюється", "Вона ніколи не запізнюється", "Вона сьогодні запізнилася"], "Often late — часто запізнюється."),
  fb("I ___ have a shower in the morning. Every day!", ["always", "never", "sometimes"], "Every day — це always."),
  bs("Я часто їжджу автобусом.", ["I", "often", "take", "the", "bus"], ["never", "by"], "I often take the bus."),
  tr("Я завжди снідаю.", ["I always have breakfast"], "I always have breakfast."),
  li("Do you have breakfast every day?", "Ви не снідаєте взагалі. Що відповісти?", ["No, I never have breakfast.", "No, I always have breakfast.", "No, I don't never."], "No, I never have breakfast.")])
L(4, "Спочатку, потім, після", "Розповісти про ранок по порядку.",
 "First — «спочатку», then — «потім». Before — «перед», after — «після»: before work, after breakfast. Make — «робити, готувати»: make coffee, make breakfast, make the bed (застеляти ліжко).",
 [W("first", "/fɜːst/", "adverb", "спочатку", "First I have a shower.", "Спочатку я приймаю душ."),
  W("before", "/bɪˈfɔː/", "preposition", "перед, до", "Before work.", "Перед роботою."),
  W("after", "/ˈɑːftə/", "preposition", "після", "After breakfast.", "Після сніданку."),
  W("make", "/meɪk/", V, "робити, готувати", "I make coffee.", "Я готую каву."),
  W("check", "/tʃek/", V, "перевіряти", "I check my phone.", "Я перевіряю телефон."),
  W("quick", "/kwɪk/", "adjective", "швидкий", "A quick breakfast.", "Швидкий сніданок.")],
 [fb("I ___ drink coffee. I don't like it.", ["never", "always", "often"], "Never — ніколи.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("first", "спочатку"), ("then", "потім"), ("before", "перед"), ("after", "після")], "Слова, що показують порядок."),
  mt([("make", "готувати"), ("check", "перевіряти"), ("quick", "швидкий"), ("leave", "виходити")], "Make coffee, check my phone."),
  liu("First I have a shower, then I get dressed.", "Прослухайте. Що людина робить спочатку?", ["Приймає душ", "Одягається", "Снідає"], "First — спочатку."),
  liu("I check my phone before breakfast.", "Прослухайте. Коли людина перевіряє телефон?", ["Перед сніданком", "Після сніданку", "Під час сніданку"], "Before — перед."),
  fb("I brush my teeth ___ breakfast.", ["after", "first", "then"], "After breakfast — після сніданку."),
  fb("___ I get up, then I make coffee.", ["First", "After", "Before"], "First…, then… — спочатку…, потім…"),
  mc("Як сказати «застеляти ліжко»?", ["make the bed", "do the bed", "have the bed"], "Make the bed."),
  mcu("Що означає a quick shower?", ["Швидкий душ", "Холодний душ", "Ранковий душ"], "Quick — швидкий."),
  bs("Після сніданку я виходжу з дому.", ["After", "breakfast", "I", "leave", "home"], ["before", "the"], "After breakfast I leave home."),
  tr("Я готую каву.", ["I make coffee"], "I make coffee."),
  li("What do you do before work?", "Перед роботою ви снідаєте й перевіряєте телефон. Що відповісти?", ["I have breakfast and check my phone.", "I breakfast and my phone check.", "I'm have breakfast before."], "I have breakfast and check my phone.")])
L(5, "Її ранок", "Розповісти про ранок іншої людини.",
 "З he і she дієслово отримує -s: gets up, makes, leaves. Після ch, sh, s, o додають -es: watches, washes, goes. Have стає has. Слова частоти стоять там само: She always gets up early.",
 [W("goes", "/ɡəʊz/", V, "іде, їде (з he, she)", "She goes to work by bus.", "Вона їздить на роботу автобусом."),
  W("wash", "/wɒʃ/", V, "мити", "He washes his face.", "Він умивається."),
  W("face", "/feɪs/", "noun", "обличчя", "I wash my face.", "Я вмиваюся."),
  W("alarm", "/əˈlɑːm/", "noun", "будильник", "My alarm is at six.", "Мій будильник на шосту."),
  W("in a hurry", "/ɪn ə ˈhʌri/", "phrase", "поспіхом", "He's always in a hurry.", "Він завжди поспішає.")],
 [fb("___ I have a shower, then I get dressed.", ["First", "After", "Never"], "First…, then…", "Повторимо. Оберіть слово, якого бракує"),
  mt([("goes", "іде, їде"), ("wash", "мити"), ("face", "обличчя"), ("alarm", "будильник"), ("in a hurry", "поспіхом")], "Нові слова про ранок."),
  fb("She ___ up at six.", ["gets", "get", "getting"], "З she — gets."),
  fb("He ___ to work by car.", ["goes", "go", "gos"], "Go → goes."),
  fb("My brother ___ breakfast at seven.", ["has", "have", "haves"], "Have → has."),
  mc("Як правильно написати?", ["washes", "washs", "washies"], "Після sh — -es: washes."),
  mc("Як правильно?", ["She always gets up early.", "She gets always up early.", "She always get up early."], "Always перед дієсловом, і дієслово з -s."),
  liu("He leaves home at seven and takes the train.", "Прослухайте. Як він їде на роботу?", ["Поїздом", "Автобусом", "Машиною"], "Takes the train."),
  liu("My wife is always in a hurry in the morning.", "Прослухайте. Що ви дізналися?", ["Дружина вранці завжди поспішає", "Дружина вранці ніколи не поспішає", "Дружина завжди запізнюється"], "In a hurry — поспіхом."),
  bs("Він умивається.", ["He", "washes", "his", "face"], ["wash", "her"], "He washes his face."),
  tr("Вона їздить на роботу автобусом.", ["She goes to work by bus", "She takes the bus to work"], "She goes to work by bus."),
  li("What time does your husband get up?", "Ваш чоловік встає о пів на шосту. Що відповісти?", ["He gets up at half past five.", "He get up at half past five.", "He gets up on half past five."], "He gets up at half past five.")])
L(6, "Повторення: мій ранок", "Зв'язно розповісти про свій ранок і про ранок близької людини.",
 "Нових слів немає. Складаємо розповідь: коли встаю, що роблю спочатку й потім, як часто, як їду на роботу. І те саме про іншу людину — з -s.",
 [],
 [bs("Я завжди встаю о сьомій.", ["I", "always", "get", "up", "at", "seven"], ["gets", "on"], "I always get up at seven."),
  fb("First I have a shower, ___ I have breakfast.", ["then", "before", "never"], "First…, then…"),
  fb("She ___ her teeth after breakfast.", ["brushes", "brush", "brushs"], "Після sh — -es: brushes."),
  tr("Я ніколи не п'ю кави.", ["I never drink coffee"], "I never drink coffee."),
  liu("I wake up at six, check my phone and make coffee.", "Прослухайте. Що людина робить після того, як прокинеться?", ["Перевіряє телефон і готує каву", "Приймає душ і снідає", "Одягається й виходить"], "Check my phone, make coffee."),
  mc("Як правильно?", ["He sometimes walks to work.", "He walks sometimes to work.", "He sometimes walk to work."], "Sometimes перед дієсловом, дієслово з -s."),
  fb("I go to work ___ foot.", ["on", "by", "at"], "On foot."),
  tr("Вона починає роботу о дев'ятій.", ["She starts work at nine", "She starts work at nine o'clock"], "She starts work at nine."),
  liu("My son never makes the bed. He's always in a hurry.", "Прослухайте. Чого син ніколи не робить?", ["Не застеляє ліжко", "Не снідає", "Не чистить зуби"], "Never makes the bed."),
  li("How do you go to work?", "Ви зазвичай їздите поїздом. Що відповісти?", ["I usually take the train.", "I take usually train.", "I usually by train take."], "I usually take the train."),
  li("What do you do after breakfast?", "Після сніданку ви чистите зуби й виходите. Що відповісти?", ["I brush my teeth and leave home.", "I brush teeth my and home leave.", "I'm brush and leave."], "I brush my teeth and leave home."),
  tr("Після роботи я йду додому пішки.", ["After work I walk home", "I walk home after work"], "After work I walk home.")],
 review=True)
